package com.meterflow.payments;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import java.util.*;
@RestController @RequestMapping("/api/dunning")public class DunningController{private final DunningService service;public DunningController(DunningService s){service=s;}@GetMapping @PreAuthorize("hasRole('ADMIN')")public List<DunningCase> all(){return service.all();}@PostMapping("/{invoiceId}/failed")public DunningCase failed(@PathVariable UUID invoiceId){return service.recordFailure(invoiceId);}@PostMapping("/{invoiceId}/succeeded")public DunningCase succeeded(@PathVariable UUID invoiceId){return service.recordSuccess(invoiceId);}}
